static void saveFrame(const std::string& out,const char* name,int w,int h){auto*f=std::fopen((out+"/"+name+".ppm").c_str(),"wb");assert(f);std::fprintf(f,"P6\n%d %d\n255\n",w,h);for(int y=0;y<h;++y)for(int x=0;x<w;++x){auto p=PixelRenderer::canvas().readPixel(x,y);const unsigned char rgb[]={uint8_t(((p>>11)&31)*255/31),uint8_t(((p>>5)&63)*255/63),uint8_t((p&31)*255/31)};std::fwrite(rgb,1,3,f);}assert(!std::fclose(f));}
template<class UI>static void clips(UI&ui,const Game::GameState&s,int w,int h){auto& c=PixelRenderer::canvas();for(bool swap:{false,true}){std::vector<uint16_t>pix(w*h);c.attach({pix.data(),uint16_t(w),uint16_t(h),swap});c.setCoordinateScale(1);c.setLayoutScale(1);c.setAssetScale(1);c.setNativeText(w==368);c.clearClipRect();c.fillSprite(0x31a5);ui.render(s);const auto expected=pix;c.fillSprite(0x31a5);for(int y=0;y<h;y+=13){c.setClipRect(0,y,w,std::min(13,h-y));ui.render(s);}assert(pix==expected);c.clearClipRect();}}
